$A=\begin{pmatrix}0&-i\\ i&0\end{pmatrix}$ について考える．
\begin{enumerate}
\item $U^\dagger A U=\begin{pmatrix}1&0\\0&-1\end{pmatrix}$ を満たすユニタリ行列 $U$ を 1 つ求めよ．また，同じ条件を満たすユニタリ行列の一般形を答えよ．
\item 実直交行列 $O$（$O^{T}O=I$，成分はすべて実数）で $O^{T}AO=\begin{pmatrix}1&0\\0&-1\end{pmatrix}$ となるものは存在しないことを示せ．
\item 実数 $\alpha$ に対して $R(\alpha)=\exp\!\left(-\dfrac{i\alpha}{2}A\right)$ を (1) の対角化を用いて計算し，$R(\alpha)$ が実行列になることを示せ．$R(\alpha)$ を実ベクトル $(x,y)^{T}$ に作用させると何が起こるか．また $R(2\pi)$ を求めよ．
\end{enumerate}

\begin{enumerate}
\item ユニタリ行列 $V$（$V^\dagger V=I$）の固有方程式 $V|n\rangle=v_n|n\rangle$（$\langle n|n\rangle=1$）について，$|v_n|=1$ であること，および $v_n\neq v_m$ なら $\langle n|m\rangle=0$ であることを示せ．
\item 行列 $B=\begin{pmatrix}1&1\\0&2\end{pmatrix}$ はエルミートでないが，固有値は実数である．固有値 $\lambda_1=1,\lambda_2=2$ に対する規格化された右固有ベクトル $|r_1\rangle,|r_2\rangle$（第 1 成分を正にとる）を求め，$|\langle r_1|r_2\rangle|$ を計算せよ．このとき $\sum_n|r_n\rangle\langle r_n|$ は単位行列になるか．
\item $B$ の左固有ベクトル（行ベクトル）$\langle l_n|$ を $\langle l_n|B=\lambda_n\langle l_n|$，$\langle l_n|r_m\rangle=\delta_{nm}$ を満たすように定める．$\langle l_1|,\langle l_2|$ を求め，$\sum_n|r_n\rangle\langle l_n|=I$ および $B=\sum_n\lambda_n|r_n\rangle\langle l_n|$ を確かめよ．
\end{enumerate}

1 次元の粒子について，並進演算子 $U(a)=e^{-iap/\hbar}$ と運動量ブースト演算子 $V(b)=e^{ibx/\hbar}$（$a,b$ は実数）を考える．$U(a)$ は $(U(a)\psi)(x)=\psi(x-a)$ と作用する．
\begin{enumerate}
\item $U(a)^\dagger x\,U(a)=x+a$，$V(b)^\dagger p\,V(b)=p+b$ を示せ．
\item $U(a)V(b)=e^{i\phi}V(b)U(a)$ となる位相 $\phi$ を求めよ．
\item $xp$ はエルミートでないことを，実数値の規格化された波動関数 $\psi(x)$ に対して $\langle xp\rangle$ を計算することで示せ．また $xp$ をエルミート部分と反エルミート部分に分けよ．
\end{enumerate}

1 次元の粒子（質量 $m$）が $H=\dfrac{p^2}{2m}+\lambda x^4$（$\lambda>0$）に従う．$[x,p]=i\hbar$ とする．
\begin{enumerate}
\item 任意の滑らかな関数 $f(x)$ に対し $[f(x),p]=i\hbar f'(x)$ を示せ．
\item 交換子 $[xp,\,H]$ を $p$ と $x$ で表せ．
\item $H$ の固有値 $E$ の固有状態における運動エネルギーの期待値 $\langle T\rangle$ とポテンシャルエネルギーの期待値 $\langle V\rangle$ を $E$ で表せ．
\end{enumerate}

2 次元複素ベクトル空間 $\mathbb C^2$ に内積 $(\phi,\psi)=\sum_i\phi_i^*\psi_i$ を入れ，演算子 $K$ を成分ごとの複素共役 $K\psi=\psi^*$ で定める．
\begin{enumerate}
\item $K$ は線形でないこと（反線形 $K(\lambda\psi)=\lambda^*K\psi$）を示し，$(K\phi,K\psi)=(\psi,\phi)$ を示せ．
\item 演算子 $H$ が任意の $\phi,\psi$ に対し $(\phi,H\psi)=(H\phi,\psi)$ を満たすならば，$H$ は必ず線形であることを示せ．
\item (2) から $K$ はこの意味でエルミートではありえない．具体的に $\phi=(1,0)^T$，$\psi=(i,0)^T$ に対して $(\phi,K\psi)$ と $(K\phi,\psi)$ を計算して確かめよ．
\end{enumerate}

実数 $\alpha,\beta$ を用いて $A=\alpha x+i\beta p$ と定める（$[x,p]=i\hbar$）．
\begin{enumerate}
\item $A^\dagger$，$[A,A^\dagger]$，$A^\dagger A$ を $x,p$ で表せ．
\item $\alpha,\beta>0$ のとき $A\psi_0=0$ を満たす規格化可能な $\psi_0(x)$ を求め，その状態で $\Delta x$，$\Delta p$ を計算して $\Delta x\Delta p$ を求めよ．$\alpha\beta<0$ ではどうなるか．
\item 調和振動子 $H=\dfrac{p^2}{2m}+\dfrac12m\omega^2x^2$ が $H=\hbar\omega\left(A^\dagger A+\tfrac12\right)$ と書けるための $\alpha,\beta$（正）を求めよ．
\end{enumerate}

\begin{enumerate}
\item 任意の演算子 $A,B$ について $[A^n,B]=\sum_{k=0}^{n-1}A^k[A,B]A^{n-1-k}$ を示せ．さらに $[A,B]$ が $A$ と可換なら $[A^n,B]=n[A,B]A^{n-1}$，したがってべき級数で表される関数 $f$ について $[f(A),B]=[A,B]f'(A)$ となることを示せ．
\item 調和振動子の昇降演算子（$[a,a^\dagger]=1$，$a|0\rangle=0$）に (1) を適用し，$[a,(a^\dagger)^n]$ と $[a,e^{\lambda a^\dagger}]$（$\lambda$ は複素数）を求めよ．
\item $|\lambda\rangle=e^{\lambda a^\dagger}|0\rangle$ が $a$ の固有状態であることを示し，固有値とノルムの 2 乗 $\langle\lambda|\lambda\rangle$ を求めよ．
\end{enumerate}

角振動数 $\omega$ の 1 次元調和振動子（質量 $m$）の状態が，基底状態 $\psi_0$ と第 1 励起状態 $\psi_1$ の重ね合わせ $\Psi(0)=C_0\psi_0+C_1\psi_1$（$|C_0|^2+|C_1|^2=1$）で与えられている．エネルギーの期待値は $\tfrac54\hbar\omega$ であった．$\langle\psi_0|x|\psi_1\rangle=\sqrt{\hbar/2m\omega}$（$\psi_0,\psi_1$ は実関数）とする．
\begin{enumerate}
\item $|C_0|^2,\ |C_1|^2$ を求めよ．
\item $\langle x\rangle(t)$ を求め，その振動の振幅を求めよ．また，$\langle x\rangle(0)$ が取りうる最大値と，そのときの $C_0,C_1$ の相対位相の条件を述べよ．
\item エネルギーの標準偏差 $\Delta E$ を求めよ．
\end{enumerate}

無次元化した調和振動子のシュレーディンガー方程式 $-\psi''+R^2\psi=\varepsilon\psi$（$R=x/a$，$a=\sqrt{\hbar/m\omega}$，$\varepsilon=2E/\hbar\omega$）に $\psi=H(R)e^{-R^2/2}$ を代入すると $H''-2RH'+(\varepsilon-1)H=0$ を得る．
\begin{enumerate}
\item $H=\sum_j c_jR^j$ として係数の漸化式を求め，級数が打ち切られる条件から $\varepsilon$ を求めよ．
\item $\varepsilon=7$ のときの多項式解 $H(R)$ を最高次の係数が $8$ になるように求めよ．
\item ポテンシャルが $x>0$ で $\frac12m\omega^2x^2$，$x\le0$ で $+\infty$（壁）のとき，エネルギー固有値を求めよ．
\end{enumerate}

調和振動子 $V=\frac12m\omega^2x^2$ を考え，$a=\sqrt{\hbar/m\omega}$ とする．誤差関数 $\mathrm{erfc}(z)=\frac2{\sqrt\pi}\int_z^\infty e^{-t^2}dt$ を用い，$\gamma\equiv\mathrm{erfc}(\sqrt3)$ とおく．
\begin{enumerate}
\item 1 次元の第 1 励起状態 $\psi_1=\left(\frac{4}{\pi a^2}\right)^{1/4}\frac xa e^{-x^2/2a^2}$ について，粒子が古典的禁止領域に見いだされる確率 $P_1$ を $\gamma$ を用いて表せ．基底状態の値 $\mathrm{erfc}(1)$ と比べてどちらが大きいか（数表の値を用いてよい）．
\item 3 次元等方調和振動子 $V=\frac12m\omega^2r^2$ の基底状態について，古典的禁止領域（$V>E$）に見いだされる確率 $P_3$ を $\gamma$ を用いて表せ．
\item (1) と (2) の答えが一致する理由を説明せよ．
\end{enumerate}

3 次元等方調和振動子 $V=\frac12m\omega^2r^2$ のエネルギー準位は $E_N=\left(N+\frac32\right)\hbar\omega$（$N=n_x+n_y+n_z$）である．
\begin{enumerate}
\item 球座標で解くと $E=(2n_r+l+\frac32)\hbar\omega$（$n_r=0,1,\dots$）となる．これを認めて，$N=0,1,2,3,4$ の各準位に含まれる軌道角運動量 $l$ の値を列挙し，$\sum(2l+1)$ が直交座標で数えた縮退度に一致することを確かめよ．
\item 原子核の殻模型で，核子（スピン 1/2）をこの準位に下から詰めていくとき，準位 $N$ が閉じるごとの核子の累積数（陽子または中性子のみ）を $N=0$ から $4$ まで求めよ．実際の魔法数 $2,8,20,28,50$ と比較し，どこで食い違うか述べよ．
\end{enumerate}

調和振動子 $H=\frac{p^2}{2m}+\frac12m\omega^2x^2$ について，$x_0=\sqrt{\hbar/m\omega}$ とする．
\begin{enumerate}
\item エネルギー $E$ の古典的振動 $x=A\cos\omega t$ について，時間平均 $\overline{x^2}$，$\overline{x^4}$ を $E$ で表せ．
\item 生成・消滅演算子 $x=\frac{x_0}{\sqrt2}(a+a^\dagger)$ を用いて，量子状態 $|n\rangle$ での $\langle x^2\rangle$，$\langle x^4\rangle$ を求めよ．
\item $E=(n+\frac12)\hbar\omega$ として (1)(2) を比較し，$\langle x^2\rangle$ は任意の $n$ で古典値と一致するのに対し，$\langle x^4\rangle$ は $n$ によらない一定のずれをもつことを示せ．そのずれを求め，$n\to\infty$ で相対的に 0 になることを確かめよ．
\end{enumerate}

\begin{enumerate}
\item $d$ 次元等方調和振動子のエネルギーは $E=(N+\frac d2)\hbar\omega$，$N=n_1+\dots+n_d$ である．準位 $N$ の縮退度 $g_d(N)$ を求め，$d=3$ の場合を $N$ の多項式で表せ．
\item 角振動数が $\omega_x=\omega_y=\omega$，$\omega_z=2\omega$ の非等方振動子を考える．エネルギーを $E=(M+2)\hbar\omega$ と書いたとき，$M=n_x+n_y+2n_z$ となる．準位 $M$ の縮退度を $M=2k$（偶数）・$M=2k+1$（奇数）の場合に分けて $k$ で表せ．
\item (2) で $M=4$（$E=6\hbar\omega$）の準位の縮退度を求めよ．等方振動子（$\omega_z=\omega$）にエネルギー $6\hbar\omega$ の準位はあるか．
\end{enumerate}

調和振動子 $V=\frac12m\omega^2x^2$ について $x_0=\sqrt{\hbar/m\omega}$ とし，$\psi_n$ を実の規格化された固有関数とする．
\begin{enumerate}
\item $\Psi(x,0)=\frac1{\sqrt2}(\psi_0+\psi_1)$ のとき，$|\Psi(x,t)|^2$ が角振動数 $\omega$ で振動することを示し，$\langle x\rangle(t)$ を求めよ．
\item $\psi_0$ と $\psi_1$ だけからなる規格化された任意の状態 $c_0\psi_0+c_1\psi_1$ のうち，$\langle x\rangle$ の振動の振幅が最大になるものとその振幅を求めよ．
\item $\Psi(x,0)=\frac1{\sqrt2}(\psi_0+\psi_2)$ のとき，$\langle x\rangle(t)=0$ であるが確率密度は振動する．その角振動数を求め，$\langle x^2\rangle(t)$ を求めよ．
\end{enumerate}

$a=\sqrt{\hbar/m\omega}$ とし，$\psi_1(x)=Bx\,e^{-x^2/2a^2}$ を考える．
\begin{enumerate}
\item $\psi_1$ が $V=\frac12m\omega^2x^2$ のシュレーディンガー方程式をエネルギー $\frac32\hbar\omega$ で満たすことを示せ．
\item $x\le0$ に無限に高い壁を置いた半調和振動子（$x>0$ で $V=\frac12m\omega^2x^2$）の基底状態は $x>0$ に制限した $\psi_1$ であることを説明し，$x>0$ で規格化したときの $\langle x\rangle$，$\Delta x$ を求めよ．
\item この基底状態で $\langle p\rangle$，$\Delta p$ を求め，$\Delta x\,\Delta p$ を $\hbar$ を用いて厳密に表せ．
\end{enumerate}

電荷 $q>0$，質量 $m$ の粒子が $xy$ 平面内を運動し，一様な磁場 $B\hat z$，一様な電場 $E\hat x$，および $x$ 方向の閉じ込めポテンシャル $\frac12m\omega_0^2x^2$ を受ける．ベクトルポテンシャルを $\boldsymbol A=(0,Bx,0)$ とし，$\omega_c=qB/m$，$\Omega=\sqrt{\omega_c^2+\omega_0^2}$ とおく．
\begin{enumerate}
\item 波動関数を $\psi=e^{iky}\phi(x)$ として $\phi$ の方程式を求め，エネルギー固有値 $E_{n,k}$ を求めよ．
\item 固有状態での $y$ 方向の速度の期待値 $v_y(k)=\dfrac1\hbar\dfrac{\partial E_{n,k}}{\partial k}$ を求めよ．
\item $\omega_0\to0$ で $v_y$ が $k$ によらない値になることを示し，その値を求めよ．
\end{enumerate}

電荷 $q$，質量 $m$ の粒子が磁場 $B\hat z$ と電場 $E\hat x$ の中で $xy$ 面を動く．ランダウゲージ $\boldsymbol A=(0,Bx,0)$ で $H=\dfrac{1}{2m}[p_x^2+(p_y-qBx)^2]-qEx$．
\begin{enumerate}
\item $\psi=e^{iky}f(x)$ とおき，エネルギー固有値を求めよ．
\item 状態 $(n,k)$ の $y$ 方向の群速度 $\frac1\hbar\frac{\partial E}{\partial k}$ を求め，$\boldsymbol E\times\boldsymbol B/B^2$ と比べよ．
\end{enumerate}

実関数 $W(x)$ を用いて $A=\dfrac{\hbar}{\sqrt{2m}}\left(\dfrac{d}{dx}+W(x)\right)$ と定義する．
\begin{enumerate}
\item $A^\dagger A$ と $AA^\dagger$ を微分演算子として書け．また任意の状態で $\langle A^\dagger A\rangle\ge0$ であることを示せ．
\item $W=\kappa\tanh(\kappa x)$（$\kappa>0$）とすると，$H=-\dfrac{\hbar^2}{2m}\dfrac{d^2}{dx^2}-\dfrac{\hbar^2\kappa^2}{m}{\rm sech}^2(\kappa x)$ が $H=A^\dagger A-\dfrac{\hbar^2\kappa^2}{2m}$ と書けることを示し，$H$ の基底エネルギーと基底状態（未規格化でよい）を求めよ．
\item 同じ $W$ で $AA^\dagger$ を計算し，その結果から「$H$ の束縛状態は (2) で求めた 1 つだけである」ことを示せ．（ヒント：$A^\dagger A\psi=\epsilon\psi$，$\epsilon>0$ なら $A\psi$ は $AA^\dagger$ の同じ固有値の固有関数．）
\end{enumerate}

質量 $\mu$ の粒子のハミルトニアンを $H=\dfrac{p^2}{2\mu}+V(x)$，固有状態を $|n\rangle$（エネルギー $E_n$，$n=0$ が基底状態）とする．
\begin{enumerate}
\item $[[x,H],x]=\hbar^2/\mu$ を示せ．
\item (1) の基底状態期待値をとり，トーマス・ライヒェ・クーン（TRK）総和則
\[
\sum_n(E_n-E_0)|\langle n|x|0\rangle|^2=\frac{\hbar^2}{2\mu}
\]
を導け．これを用いて，第 1 励起エネルギー $\Delta=E_1-E_0$ と基底状態の位置の広がり $\Delta x$ の間に $\Delta\cdot(\Delta x)^2\le\hbar^2/2\mu$ が成り立つことを示せ．
\item 幅 $L$ の無限井戸（$0\le x\le L$）の基底状態について $(\Delta x)^2=L^2\left(\dfrac1{12}-\dfrac1{2\pi^2}\right)$ である．比 $\Delta\cdot(\Delta x)^2\big/(\hbar^2/2\mu)$ を厳密に求め，(2) の不等式を確かめよ．調和振動子ではこの比はいくらか．
\end{enumerate}

質量 $m$ の粒子が角振動数 $\omega_0$ の調和振動子の基底状態にある．時刻 $0$ にばね定数が突然変わり，角振動数が $\omega_1$ になった．
\begin{enumerate}
\item 新しい振動子の基底状態に見いだす確率 $P_0$ を $\omega_0,\omega_1$ で求めよ．
\item $\omega_1=2\omega_0$ のとき，新しい振動子の第1励起状態，第2励起状態に見いだす確率 $P_1,P_2$ を求めよ．
\item $\omega_1=2\omega_0$ のとき，変化直後のエネルギーの期待値 $\langle H_1\rangle$ を求めよ（$H_1$ は変化後のハミルトニアン）．
\end{enumerate}
